INSERT INTO langs (Id, French) VALUES (9099000, 'Coiffe du Mominotor'),
 (9099001, 'Si vous voulez préserver votre visage des affres du temps, nous vous conseillons cette coiffe. Attention, elle est totalement inefficace pour vous protéger des pertes de mémoire.'),
 (9099002, 'Pendentif du Mominotor'),
 (9099003, 'Ce pendentif maudit recouvert de bandelettes vous permettra peut-être de survivre à la malédiction du labyrinthe du Minotoror. Mais rien n''est moins sûr, peut-être n''est-ce qu''un bibelot destiné à épater les touristes.'),
 (9099004, 'Alliance du Mominotor'),
 (9099005, 'Cet anneau confectionné à partir de bandelettes de Mominotor enroulées sur elles-mêmes, sent plutôt mauvais, et est assez laid, mais fera un très bon pansement lorsque vous vous coincerez un doigt dans une des portes du labyrinthe du Minotoror.'),
 (9099006, 'Marteau du Mominotor'),
 (9099007, 'Le bloc de pierre à l''extrémité de ce marteau, est enroulé dans des bandelettes du Mominotor afin d''absorber les fluides qui s''échapperont des créatures que vous écraserez, ou tout simplement leur faire moins mal, et ne pas les tuer trop rapidement.'),
 (9099008, 'Bottes du Mominotor'),
 (9099009, 'Rembourrées et décorées avec des bandelettes de Mominotor, ces bottes sont à la fois très confortables et très chaudes. Elles vous rappellent peut-être quelqu''un.'),
 (9099010, 'Cape du Mominotor'),
 (9099011, 'Confectionnée à partir de bandelettes du Mominotor tressées entre elles, cette cape vous donnera un style tout droit sorti d''outre-tombe. Vos ennemis risquent de crever de jalousie.'),
 (9099012, 'Chapeau du Directeur Grunob'),
 (9099013, 'Doté de ce couvre-chef rapiécé, vous serez capable de toutes les prouesses que l''on attribue aux mages gobelins : disparition de chaussettes, concoction de potions douteuses... Et bien plus encore !'),
 (9099014, 'Bottes du Directeur Grunob'),
 (9099015, 'Prenez garde à la réaction de Vermô le gobelin en vous rendant au Bibliotemple muni de ces bottes, car vous risqueriez de lui rappeler quelques épisodes traumatisants de son adolescence.
En effet, il ne compte plus le nombre de fois où suite à une farce trop bruyante, il entendait les pas du Directeur Grunob résonner dans les couloirs de l''Akadémie, précédant le sermon mémorable qui l''attendait.'),
 (9099016, 'Ceinture du Directeur Grunob'),
 (9099017, 'Un ruban de tissu orangé teint à base d''extraits de cawotte. Il est couvert de poils de chacha de la même couleur. Pensez-vous qu''il soit possible de teindre un chacha pour l''assortir à votre look ?'),
 (9099018, 'Faux du Directeur Grunob'),
 (9099019, 'La forme de sa lame rend cet outil idéal pour gratter les crottes de nez collées sous les tables.'),
 (9099020, 'Panoplie Autochtone'),
 (9099021, 'Panoplie du Grolandais'),
 (9099022, 'Panoplie du frigostien curieux'),
 (9099023, 'Panoplie Ensevelie'),
 (9099024, 'Panoplie du Poolay'),
 (9099025, 'Panoplie du Fourneau'),
 (9099026, 'Panoplie de la Fournaise'),
 (9099027, 'Panoplie du Mominotor'),
 (9099028, 'Panoplie du Directeur Grunob'),
 (9099029, 'Panoplie du Tynril');
